content.problemStatement:
You are given a function,
char* FindMax(int* arr, int size);
char* FindMax(int* arr, int size);
static String FindMax(int[] arr){}
static string FindMax(int[] arr){}
def FindMax(arr):
The function accepts an integer array 'arr' of length 'size' as its argument. Implement the function
to find and return the maximum number that can be formed by any permutation or arrangement of
all the digits obtained from all the numbers present in the array. You have to return the number
formed as a string.
Note: You may need to rearrange the digits of the numbers to form the maximum number.

code.C:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
int cmp(const void *a, const void *b) { return (*(char*)b - *(char*)a); }
int main() {
    int n; if (scanf("%d", &n) != 1) return 0;
    char digits[100000]; int idx = 0;
    for (int i = 0; i < n; i++) {
        char buf[50]; scanf("%s", buf);
        for (int k = 0; buf[k]; k++) if (buf[k] >= '0' && buf[k] <= '9') digits[idx++] = buf[k];
    }
    digits[idx] = '\0';
    qsort(digits, idx, 1, cmp);
    puts(digits);
    return 0;
}

code.C++:
#include <iostream>
#include <string>
#include <vector>
#include <algorithm>
using namespace std;
int main() {
    int n; if (cin >> n) {
        string digits = "";
        for (int i = 0; i < n; i++) {
            string s; cin >> s;
            for (char c : s) if (isdigit(c)) digits += c;
        }
        sort(digits.rbegin(), digits.rend());
        cout << digits << "\n";
    }
    return 0;
}

code.Java:
import java.util.Scanner;
import java.util.ArrayList;
import java.util.Collections;
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (sc.hasNextInt()) {
            int n = sc.nextInt();
            ArrayList<Character> digits = new ArrayList<>();
            for (int i = 0; i < n; i++) {
                String s = sc.next();
                for (char c : s.toCharArray()) if (Character.isDigit(c)) digits.add(c);
            }
            Collections.sort(digits, Collections.reverseOrder());
            StringBuilder sb = new StringBuilder();
            for (char c : digits) sb.append(c);
            System.out.println(sb.toString());
        }
    }
}

