import sys
def main():
    toks = sys.stdin.read().split()
    if toks:
        n = int(toks[0])
        digits = []
        for x in toks[1:1+n]:
            for d in str(abs(int(x))):
                digits.append(d)
        digits.sort(reverse=True)
        print("".join(digits))
if __name__ == "__main__": main()

code.JavaScript:
const fs = require("fs");
function main() {
    const toks = fs.readFileSync(0, "utf-8").trim().split(/\s+/);
    if (toks.length > 0) {
        const n = parseInt(toks[0], 10);
        const digits = [];
        for (let i = 1; i <= n && i < toks.length; i++) {
            for (const d of Math.abs(parseInt(toks[i], 10)).toString()) {
                digits.push(d);
            }
        }
        digits.sort((a, b) => b.localeCompare(a));
        console.log(digits.join(""));
    }
}
main();

